UPDATE /* uptNicknameSequence */
       TB_NKSEQX
   SET LAST_NUMB = LAST_NUMB + 1
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE SUBJ_CODE = #{subjCode}
   AND PRED_CODE = #{predCode}
   AND ANML_CODE = #{anmlCode}
   AND ISSU_YEAM = DATE_FORMAT(CURRENT_TIMESTAMP, '%y%m')
   AND LAST_NUMB < #{maxSequence}

